289|static char* ini_reader_string(char* str, int num, void* stream) {
290|    ini_parse_string_ctx* ctx = (ini_parse_string_ctx*)stream;
291|    const char* ctx_ptr = ctx->ptr;
292|    size_t ctx_num_left = ctx->num_left;
293|    char* strp = str;
294|    char c;
295|
296|    if (ctx_num_left == 0 || num < 2)
297|        return NULL;
298|
299|    while (num > 1 && ctx_num_left != 0) {
300|        c = *ctx_ptr++;
301|        ctx_num_left--;
302|        *strp++ = c;
303|        if (c == '\n')
304|            break;
305|        num--;
306|    }
307|
308|    *strp = '\0';
309|    ctx->ptr = ctx_ptr;
310|    ctx->num_left = ctx_num_left;
311|    return str;
312|}

